import sys
import inspect
from functools import partial
from .compat import PY2


__all__ = ['decorator', 'wraps', 'unwrap', 'ContextDecorator', 'contextmanager',
           'decorator_fab', 'func', 'get_argnames', 'has_1pos_and_kwonly', 'has_single_arg',
           'rate_limit']


def decorator(deco):
    """
    Transforms a flat wrapper into decorator::

        @decorator
        def func(call, methods, content_type=DEFAULT):  # These are decorator params
            # Access call arg by name
            if call.request.method not in methods:
                # ...
            # Decorated functions and all the arguments are accesible as:
            print(call._func, call_args, call._kwargs)
            # Finally make a call:
            return call()
    """
    if has_single_arg(deco):
        return make_decorator(deco)
    elif has_1pos_and_kwonly(deco):
        # Function with 1 positional arg + optional keyword-only args
        return _make_decorator_kwonly(deco)
    else:
        # Any arguments after first become decorator arguments
        # And a decorator with arguments is essentially a decorator fab
        def decorator_fab(*dargs, **dkwargs):
            return make_decorator(deco, dargs, dkwargs)
        return wraps(deco)(decorator_fab)


def has_1pos_and_kwonly(func):
    """Check if function has exactly 1 positional arg and only keyword-only args."""
    if PY2:
        spec = inspect.getfullargspec(func) if hasattr(inspect, 'getfullargspec') else inspect.getargspec(func)
        # In Python 2, we can't really check kwonlyargs easily
        if hasattr(spec, 'kwonlyargs'):
            return len(spec.args) == 1 and not spec.varargs and not spec.keywords
        return False
    else:
        spec = inspect.signature(func)
        pos_count = 0
        for param in spec.parameters.values():
            if param.kind in (inspect.Parameter.POSITIONAL_ONLY, 
                              inspect.Parameter.POSITIONAL_OR_KEYWORD):
                pos_count += 1
            elif param.kind == inspect.Parameter.KEYWORD_ONLY:
                continue  # keyword-only args are OK
            else:
                return False  # VAR_POSITIONAL or VAR_KEYWORD not allowed
        return pos_count == 1


def _make_decorator_kwonly(deco):
    """Create a decorator factory for functions with 1 positional + kwonly args."""
    spec = inspect.signature(deco)
    params = list(spec.parameters.values())

    # First param is 'call' (positional), rest are keyword-only with defaults
    kwonly_params = {}
    for param in params[1:]:
        if param.kind == inspect.Parameter.KEYWORD_ONLY:
            if param.default is inspect.Parameter.empty:
                raise TypeError("Keyword-only argument without default is not supported")
            kwonly_params[param.name] = param.default

    @wraps(deco)
    def _decorator(func=None, **kwds):
        if func is None:
            # Called with arguments: @decorator(arg=val)
            merged = {**kwonly_params, **kwds}
            return _make_decorator_kwonly_impl(deco, (), merged)
        else:
            # Called directly: @decorator
            return _make_decorator_kwonly_impl(deco, (), kwonly_params)

    _decorator._func = deco
    return _decorator


def _make_decorator_kwonly_impl(deco, dargs, dkwargs):
    """Internal implementation for making a decorator with specific kwargs."""
    @wraps(deco)
    def _decorator(func):
        def wrapper(*args, **kwargs):
            call = Call(func, args, kwargs)
            return deco(call, *dargs, **dkwargs)
        return wraps(func)(wrapper)

    _decorator._func = deco
    _decorator._args = dargs
    _decorator._kwargs = dkwargs
    return _decorator


class Call(object):
    """
    A call object to pass as first argument to decorator.

    Call object is just a proxy for decorated function
    with call arguments saved in its attributes.
    """
    def __init__(self, func, args, kwargs):
        self._func, self._args, self._kwargs = func, args, kwargs

    def __call__(self, *a, **kw):
        if not a and not kw:
            return self._func(*self._args, **self._kwargs)
        else:
            return self._func(*(self._args + a), **dict(self._kwargs, **kw))

    def __getattr__(self, name):
        try:
            res = self.__dict__[name] = arggetter(self._func)(name, self._args, self._kwargs)
            return res
        except TypeError as e:
            raise AttributeError(*e.args)


if PY2:
    def has_single_arg(func):
        spec = inspect.getargspec(func)
        return len(spec.args) == 1 and not spec.varargs and not spec.keywords
else:
    def has_single_arg(func):
        spec = inspect.signature(func)
        if len(spec.parameters) != 1:
            return False
        arg = next(iter(spec.parameters.values()))
        return arg.kind not in (arg.VAR_POSITIONAL, arg.VAR_KEYWORD)


def get_argnames(func):
    func = getattr(func, '__original__', None) or unwrap(func)
    return func.__code__.co_varnames[:func.__code__.co_argcount]

def arggetter(func, _cache={}):
    if func in _cache:
        return _cache[func]

    original = getattr(func, '__original__', None) or unwrap(func)
    argnames = get_argnames(original)
    indexes = dict((name, i) for i, name in enumerate(argnames))
    defaults_tuple = original.__defaults__
    if defaults_tuple:
        defaults = dict(zip(argnames[-len(defaults_tuple):], defaults_tuple))
    else:
        defaults = {}

    def get_arg(name, args, kwargs):
        if name not in indexes:
            raise TypeError("%s() doesn't have argument named %s" % (func.__name__, name))
        else:
            index = indexes[name]
            if index < len(args):
                return args[index]
            elif name in kwargs:
                return kwargs[name]
            elif name in defaults:
                return defaults[name]
            else:
                raise TypeError("%s() missing required argument: '%s'" % (func.__name__, name))

    _cache[func] = get_arg
    return get_arg


### Backport python 3.4 contextlib utilities
### namely ContextDecorator and contextmanager (also producing decorator)

if sys.version_info >= (3, 4):
    from contextlib import ContextDecorator, contextmanager
else:
    class ContextDecorator(object):
        "A base class or mixin that enables context managers to work as decorators."

        def _recreate_cm(self):
            """Return a recreated instance of self.

            Allows an otherwise one-shot context manager like
            _GeneratorContextManager to support use as
            a decorator via implicit recreation.

            This is a private interface just for _GeneratorContextManager.
            See issue #11647 for details.
            """
            return self

        def __call__(self, func):
            @wraps(func)
            def inner(*args, **kwds):
                with self._recreate_cm():
                    return func(*args, **kwds)
            return inner


    class _GeneratorContextManager(ContextDecorator):
        """Helper for @contextmanager decorator."""
        def __init__(self, gen, func, name):
            self.gen = gen
            self.func = func
            self.name = name
            self.cm = None

        def __enter__(self):
            try:
                return next(self.gen)
            except StopIteration:
                raise RuntimeError("generator didn't yield")

        def __exit__(self, exc_type, exc_val, exc_tb):
            if exc_type is None:
                try:
                    next(self.gen)
                except StopIteration:
                    return True
                else:
                    raise RuntimeError("generator didn't stop")
            else:
                if exc_val is None:
                    self.gen.throw(exc_type, None, exc_tb.__traceback__)
                else:
                    self.gen.throw(exc_type, exc_val, exc_tb.__traceback__)
            return False

        def _recreate_cm(self):
            cm = _GeneratorContextManager(self.gen, self.func, self.name)
            cm.gen = iter(self.func())
            return cm


    def contextmanager(func):
        """
        A decorator to enable a simple generator-based context manager.

        For example::

            @contextmanager
            def my_context_manager():
                setup()
                yield something
                teardown()
        """
        def helper(*args, **kwargs):
            return _GeneratorContextManager(func(), func, func.__name__)
        return helper


def update_wrapper(wrapper, wrapped, assigned=WRAPPER_ASSIGNMENTS, updated=WRAPPER_UPDATES):
    """Update a wrapper function to look like the wrapped function.

    wrapper - the function being returned
    wrapped - the function being wrapped
    """
    for attr in assigned:
        try:
            value = getattr(wrapped, attr)
        except AttributeError:
            pass
        else:
            setattr(wrapper, attr, value)
    for attr in updated:
        getattr(wrapper, attr).update(getattr(wrapped, attr, {}))

    # Set it after to not gobble it in __dict__ update
    wrapper.__wrapped__ = wrapped

    # Set an original ref for faster and more convenient access
    wrapper.__original__ = getattr(wrapped, '__original__', None) or unwrap(wrapped)

    # Return the wrapper so this can be used as a decorator via partial()
    return wrapper


def wraps(wrapped,
          assigned = WRAPPER_ASSIGNMENTS,
          updated = WRAPPER_UPDATES):
    """
    An utility to pass function metadata from wrapped function to a wrapper.
    Copies all function attributes including ``__name__``, ``__module__`` and
    ``__doc__``.

    In addition adds ``__wrapped__`` attribute referring to the wrapped function
    and ``__original__`` attribute referring to innermost wrapped one.

    Mostly used to create decorators::

        def some_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                do_something(*args, **kwargs)
                return func(*args, **kwargs)
            return wrapper

    But see also :func:`@decorator<decorator>` for that.
    This is extended version of :func:`functools.wraps`.
    """
    return partial(update_wrapper, wrapped=wrapped,
                   assigned=assigned, updated=updated)


### Backport of python 3.4 inspect.unwrap utility

try:
    from inspect import unwrap
except ImportError:
    # A simplified version, no stop keyword-only argument
    def unwrap(func):
        """
        Get the object wrapped by ``func``.

        Follows the chain of :attr:`__wrapped__` attributes returning the last
        object in the chain.

        This is a backport from python 3.4.
        """
        f = func  # remember the original func for error reporting
        memo = set([id(f)]) # Memoise by id to tolerate non-hashable objects
        while hasattr(func, '__wrapped__'):
            func = func.__wrapped__
            id_func = id(func)
            if id_func in memo:
                raise ValueError('wrapper loop when unwrapping {!r}'.format(f))
            memo.add(id_func)
        return func


# Additional exports for R5 compatibility
decorator_fab = decorator  # Alias for introspection

def rate_limit(tries=3, delay=1):
    """Rate limit decorator using @decorator pattern with keyword-only args."""
    from .flow import retry
    return retry(tries, delay)


def func(fn):
    """Identity function - returns the given function unchanged."""
    return fn
